RW.PRC = G.Knit and gcall(function() return G.Knit.GetController("PlaytimeRewardController") end)
function RW.every(k, sec) local t = RW.cd[k] if t and os.clock() < t then return false end RW.cd[k] = os.clock() + sec return true end
function RW.run()
    local pd = G.pd()
    local dr = pd.DailyReward
    if dr and RW.every("daily", 3600) then G.call("DailyRewardService", "ClaimReward", (tonumber(dr.LastClaimedDay) or 0) + 1) end
    local prc = RW.PRC
    local st = prc and tonumber(gcall(function() return prc:GetSessionTime() end)) or 0
    for i = 1, 12 do
        local c = G.C.Play and G.C.Play[i]
        if c and st >= (c.time or 0) and not RW.playDone[i] and not gcall(function() return prc:IsGiftClaimed(i) end) then
            if gcall(function() return prc:ClaimGift(i) end) then S.claims = S.claims + 1 else RW.playDone[i] = true end
            task.wait(0.3)
        end
    end
    if gcall(function() return prc and prc:GetAvailableGiftsCount() == 0 and prc:GetSessionTime() < 60 end) then RW.playDone = {} end
    if RW.every("limited", 1800) then G.call("RewardService", "ClaimLimitedReward") end
    local fs = req(CFG:FindFirstChild("FreeShopConfig"))
    if fs and pd.LastFreeShopClaim ~= fs.CURRENT_CLAIM_INDEX and RW.every("free", 600) then G.call("FreeShopService", "Claim") end
    local oc = pd.OfflineCash
    if ((type(oc) == "number" and oc > 0) or (type(oc) == "table" and next(oc) ~= nil)) and RW.every("offline", 300) then G.call("AnimalService", "CollectOfflineCash") end
    local lvl = tonumber(G.mod("SeasonPassLevel")) or 0
    local got = pd.SeasonPass and pd.SeasonPass.Free or {}
    for i = 1, lvl do if not got[i] and not got[tostring(i)] and not RW.passDone[i] then if G.call("SeasonPassService", "ClaimPassReward", "Free", i) then S.claims = S.claims + 1 end RW.passDone[i] = true end end
    local spins = 0
    while G.cur("MagiaCoins") >= 10 and spins < 5 do G.call("SpinWheelService", "SpinWheel") spins = spins + 1 task.wait(0.5) end
    if on("r_candy") and G.C.Hw and G.C.Hw.ACTIVE then
        local bought = pd.Halloween and pd.Halloween.Bought or {}
        if not bought.HW_PET_SLOT then
            if G.cur("Candy") >= 12000 then G.call("HalloweenShopService", "BuyItem", "HW_PET_SLOT") end
        elseif G.cur("Candy") >= 600 then G.call("HalloweenShopService", "BuyEgg", 1) end
    end
    if on("r_potion") then
        local inv = pd.PotionInventory or {}
        local act = pd.ActivePotions or {}
        for _, k in ipairs({ "Train", "Cash", "Luck" }) do if (tonumber(inv[k]) or 0) > 0 and not act[k] then G.call("PotionService", "UsePotion", k) end end
    end
end
